function renderLearning(){const e=document.querySelector('#lab-learning'),q=quizzes[models[active].cat[1]];e.innerHTML='<article><div class="over">DESIGN / 01</div><h3>'+ (z?'从需求到运行':'From need to operation')+'</h3><div class="lab-flow" id="lab-flow"></div><p id="lab-flow-copy"></p></article><article><div class="over">KNOWLEDGE / 02</div><h3>'+(z?'理解检查':'Knowledge check')+'</h3><p>'+t(q.q)+'</p><div class="lab-flow" id="lab-quiz"></div><p class="lab-answer" id="lab-answer" aria-live="polite"></p></article>';const f=document.querySelector('#lab-flow');function step(i){flowStep=i;f.querySelectorAll('button').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));document.querySelector('#lab-flow-copy').textContent=t(topics[i].d)}topics.forEach((topic,i)=>{let b=document.createElement('button');b.textContent=t(topic.n);b.onclick=()=>step(i);f.append(b)});step(0);const v=document.querySelector('#lab-quiz');q.a.forEach((a,i)=>{let b=document.createElement('button');b.textContent=t(a);b.onclick=()=>{v.querySelectorAll('button').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));document.querySelector('#lab-answer').textContent=i===q.ok?(z?'正确。将技术选择与实际使用和长期运营结合。':'Correct. Connect technical choices with actual use and long-term operations.'):(z?'再试一次。请回顾本模块的设计思路。':'Try again. Review the design considerations for this module.')};v.append(b)})}
function pickAt(e){const r=C.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;for(let f of hitFaces.slice().reverse()){let inside=false;for(let i=0,j=f.q.length-1;i<f.q.length;j=i++){const a=f.q[i],b=f.q[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside}if(inside){setPicked(f.idx);return}}}

const modules=document.querySelector('#lab-modules'),info=document.querySelector('#lab-info');function select(i){if(i<0)return;active=i;picked=-1;flowStep=0;exploded=false;document.querySelector('[data-act=explode]').setAttribute('aria-pressed','false');modules.querySelectorAll('button').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===Number(b.dataset.model))));let m=models[i];info.innerHTML='<div class="over">'+t(m.cat)+'</div><h2>'+t(m.n)+'</h2><dl>'+[[z?'结构组成':'Components',knowledge[i][0]],[z?'常见类型':'Common types',knowledge[i][1]],[z?'功能':'Function',m.d],[z?'应用场景':'Applications',m.a],[z?'设计思路':'Design considerations',m.p]].map(([k,v])=>'<dt>'+k+'</dt><dd>'+t(v)+'</dd>') .join('')+'</dl><div class="lab-parts" id="lab-parts"></div>';updateParts();renderLearning();render()}
const cats=document.querySelector('#lab-categories');function showCat(cat){category=cat;cats.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cat===cat)));modules.replaceChildren();let first=-1;models.forEach((m,i)=>{if(cat&&m.cat[1]!==cat)return;if(query&&!JSON.stringify([m.n,m.cat,m.d,m.a,m.p,knowledge[i]]).toLowerCase().includes(query))return;if(first<0)first=i;let b=document.createElement('button');b.dataset.model=i;b.textContent=t(m.n);b.onclick=()=>select(i);modules.append(b)});if(first<0){modules.textContent=z?'没有匹配的模型，请尝试其他关键词。':'No matching models. Try another term.';return}select(first)};[['全部','All'],...Array.from(new Map(models.map(m=>[m.cat[1],m.cat])).values())].forEach((cat,i)=>{let b=document.createElement('button');b.textContent=t(cat);b.dataset.cat=i?cat[1]:'';b.onclick=()=>showCat(b.dataset.cat);cats.append(b)});
let down=null;C.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY];drag=[e.clientX,e.clientY];C.setPointerCapture(e.pointerId)});C.addEventListener('pointermove',e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.012;pitch=Math.max(.08,Math.min(1.4,pitch+(e.clientY-drag[1])*.009));drag=[e.clientX,e.clientY];render()});C.addEventListener('pointerup',e=>{if(down&&Math.hypot(e.clientX-down[0],e.clientY-down[1])<5)pickAt(e);down=null});for(const ev of ['pointerup','pointercancel','lostpointercapture'])C.addEventListener(ev,()=>drag=null);
document.querySelectorAll('.lab-controls button').forEach(b=>b.onclick=()=>{switch(b.dataset.act){case'top':pitch=1.55;break;case'front':pitch=.08;yaw=0;break;case'left':yaw-=.3;break;case'right':yaw+=.3;break;case'up':pitch=Math.min(1.4,pitch+.15);break;case'down':pitch=Math.max(.08,pitch-.15);break;case'explode':exploded=!exploded;b.setAttribute('aria-pressed',String(exploded));break;case'night':night=!night;b.setAttribute('aria-pressed',String(night));break;case'zoomIn':zoom=Math.min(1.7,zoom*1.15);break;case'zoomOut':zoom=Math.max(.55,zoom/1.15);break;default:yaw=.65;pitch=.42;zoom=1}render()});document.querySelector('#lab-search').addEventListener('input',e=>{query=e.target.value.toLowerCase().trim();showCat(category)});C.addEventListener('keydown',e=>{const actions={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down','+':'zoomIn','-':'zoomOut',Home:'reset'};if(actions[e.key]){e.preventDefault();document.querySelector('[data-act='+actions[e.key]+']').click()}});if(typeof ResizeObserver==='function')new ResizeObserver(render).observe(C);else window.addEventListener('resize',render);showCat('')
